mapper.select:
select a.finprod_id finprodId,
bok.ACCT_SUBJECT_TYPE finprodType, bok.ACCT_MODE profitType, bok.ACCT_MODE profitTypeCode, bok.BOOKSET_NAME finprodAbbr, to_char(a.val_date, 'yyyy-MM-dd') valDate, a.val_bal_flag valBalFlag, a.val_bal_flag valBalFlagCode, nvl(a.capital,0) capiTal,
CASE WHEN b.asset_value is not null THEN b.asset_value WHEN a.asset_value is not null THEN a.asset_value ELSE 0 END as assetValue, CASE WHEN b.net_unit_value is not null THEN b.net_unit_value WHEN a.net_unit_value is not null THEN a.net_unit_value ELSE 0 END as netUnitValue,
/**add by leipeng UAT-230 单位净值、累计净值、七日年化收益率、应付利润，值不应该一直为0 20180903*/ nvl(a.total_net_value,0) totalNetNalue, nvl(a.check_status,0) checkStatus, nvl(a.check_status,0) checkStatusCode, nvl(a.check_result,0) checkResult, nvl(a.check_result,0) checkResultCode, nvl(a.confirm_status,0) confirmStatus, nvl(a.confirm_status,0) confirmStatusCode, nvl(a.notice_status,0) noticeStatus, nvl(a.notice_status,0) noticeStatusCode, nvl(a.total_net_value,0) totalNetValue, nvl(a.TDY_YIELD ,0) tdyYield, nvl(seven_day_rate,0) sevenDayRate, nvl(pay_profit,0) payProfit,
nvl(bvtd.MARKET_VALUE,0) prdTotAssetVal, nvl(bvtd.MARKET_VALUE,0)-nvl(bvtd1.MARKET_VALUE,0) prdAssetVal
from BOK_VALBAL_TABLE_STATUS a
left join bok_bookset bok on a.finprod_id = bok.BOOKSET_ID
left join BOK_VAL_TABLE_DATA bvtd on bvtd.BOOKSET_ID = a.finprod_id and bvtd.VAL_DATE = a.val_date and bvtd.DETAIL_DIST = '05' left join BOK_VAL_TABLE_DATA bvtd1 on bvtd1.BOOKSET_ID = a.finprod_id and bvtd1.VAL_DATE = a.val_date and bvtd1.DETAIL_DIST = '06'
left join BOK_VALBAL_TABLE_STATUS_ADD b on a.finprod_id = b.finprod_id and a.val_date = b.val_date
where 1=1 and bok.ACCT_SUBJECT_TYPE != #{acctSubjectType} /** 过滤通道 */
and a.val_bal_flag='01'
AND a.finprod_Id in
#{finprodId}
AND nvl(a.check_Status,0) in
#{checkStatus}
AND nvl(a.notice_Status,0) in
#{noticeStatus}
AND nvl(a.confirm_Status,0) in
#{confirmStatus}
AND bok.ACCT_MODE in
#{profitType}
AND nvl(a.check_Result,0) in
#{checkResult}
AND a.val_Date >=to_date(#{valDateBegin},'yyyy-MM-dd')
AND a.val_Date <=to_date(#{valDateEnd},'yyyy-MM-dd')
AND a.finprod_Id = #{finprodIdForFlow}
AND a.val_Date = to_date(#{valDateForFlow},'yyyy-MM-dd')
AND a.val_bal_flag = #{valBalFlagCodeForFlow}
order by a.val_Date desc

mapper.update:
      update BOK_VALBAL_TABLE_STATUS a
      set confirm_Status=#{confirmStatusCode,jdbcType=VARCHAR}
      where 1=1

		and a.finprod_Id=#{finprodId,jdbcType=VARCHAR}


		and a.val_Date=to_date(#{valDate,jdbcType=VARCHAR},'yyyy-MM-dd')


		and a.val_Bal_Flag=#{valBalFlagCode,jdbcType=VARCHAR}

      update BOK_VALBAL_TABLE_STATUS a
      set NOTICE_STATUS=#{noticeStatusCode,jdbcType=VARCHAR}
      where 1=1

		and a.finprod_Id=#{finprodId,jdbcType=VARCHAR}


		and a.val_Date=to_date(#{valDate,jdbcType=VARCHAR},'yyyy-MM-dd')


		and a.val_Bal_Flag=#{valBalFlagCode,jdbcType=VARCHAR}

mapper.select:
select count(0)
from BOK_FILE_TRANSFER bft
where bft.FINPROD_ID = #{finprodId}
  and bft.VAL_BAL_FLAG = #{valBalFlag}
  and bft.VAL_DATE = #{valDate}
  and bft.FILE_NAME = #{fileName}

mapper.delete:
        delete from BOK_FILE_TRANSFER bft
       where bft.FINPROD_ID = #{finprodId}
	     and bft.VAL_BAL_FLAG = #{valBalFlag}
	     and bft.VAL_DATE = #{valDate}
	     and bft.FILE_NAME = #{fileName}

mapper.select:
   select bncf.file_id,
       bncf.finprod_id,
       bncf.val_bal_flag,
       bncf.val_date,
       bfi.file_name
  from BOK_VALBAL_TABLE_FILE bncf
  left join BOK_FILE_INFO bfi
  on bncf.file_id = bfi.file_id
  where bncf.finprod_id = #{finprodId}
	and bncf.val_bal_flag = #{valBalFlag}
	and bncf.val_date = #{valDate}
	and bfi.file_name = #{fileName}

   select bfi.FILE_ID from 
	  BOK_FILE_INFO  bfi 
	where bfi.file_type = #{fileType}
      and bfi.file_name = #{fileName}
      and bfi.file_path = #{filePath}
